package app.morphe.extension.shared.patches;

import android.content.Context;
import android.util.Base64;
import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.zip.GZIPInputStream;
import app.morphe.extension.shared.Logger;

/**
 * Embedded official Phenotype seed data for Google Photos.
 * Automatically seeds the complete official phenotype flags (2,493 flags)
 * on first launch or after data wipe so non-root Morphe has 100% feature parity.
 */
public final class PhenotypeSeedData {
    private static final String GZ_B64_PART1 = "";
    private static final String GZ_B64_PART2 = "";

    private PhenotypeSeedData() {}

    public static void ensureSeeded(Context context) {
        try {
            File dataDir = new File(context.getApplicationInfo().dataDir);
            File prefsDir = new File(dataDir, "shared_prefs");
            File targetXml = new File(prefsDir, "com.google.android.apps.photos.phenotype.xml");

            if (!targetXml.exists() || targetXml.length() < 1000) {
                if (!prefsDir.exists()) {
                    prefsDir.mkdirs();
                }
                byte[] gzBytes = Base64.decode(GZ_B64_PART1 + GZ_B64_PART2, Base64.DEFAULT);
                try (GZIPInputStream gzis = new GZIPInputStream(new ByteArrayInputStream(gzBytes));
                     FileOutputStream fos = new FileOutputStream(targetXml)) {
                    byte[] buffer = new byte[8192];
                    int len;
                    while ((len = gzis.read(buffer)) != -1) {
                        fos.write(buffer, 0, len);
                    }
                    fos.flush();
                }
                targetXml.setReadable(true, false);
                targetXml.setWritable(true, false);
                Logger.printDebug(() -> "Successfully seeded official Phenotype XML (2,493 flags)");
            }

            File accountXml = new File(prefsDir, "phenotype_account_file.xml");
            if (!accountXml.exists()) {
                try (FileOutputStream fos = new FileOutputStream(accountXml)) {
                    fos.write("<?xml version='1.0' encoding='utf-8' standalone='yes' ?>\n<map>\n    <int name=\"account_id\" value=\"0\" />\n</map>\n".getBytes(StandardCharsets.UTF_8));
                    fos.flush();
                }
                accountXml.setReadable(true, false);
                accountXml.setWritable(true, false);
            }
        } catch (Throwable t) {
            Logger.printException(() -> "Failed to seed official phenotype data", t);
        }
    }
}
